"use strict";(globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init=globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init||[]).push([[68969],{2975(e,a,o){o.r(a),o.d(a,{assets:()=>c,contentTitle:()=>t,default:()=>u,frontMatter:()=>r,metadata:()=>n,toc:()=>l});const n=JSON.parse('{"id":"cursos/arquitectura-software/modulos/estilos-arquitectonicos/cuestionario","title":"cuestionario","description":"2. [Investigar] \xbfQu\xe9 son los \\"Self-Contained Systems\\" (SCS) y en qu\xe9 se diferencian de los microservicios y de la Service-Based Architecture?","source":"@site/docs/cursos/arquitectura-software/modulos/02-estilos-arquitectonicos/cuestionario.md","sourceDirName":"cursos/arquitectura-software/modulos/02-estilos-arquitectonicos","slug":"/cursos/arquitectura-software/modulos/estilos-arquitectonicos/cuestionario","permalink":"/sasf-temarios/cursos/arquitectura-software/modulos/estilos-arquitectonicos/cuestionario","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"private":true,"sidebar_class_name":"private","sidebar_label":"Cuestionario"},"sidebar":"cursosSidebar","previous":{"title":"Clase","permalink":"/sasf-temarios/cursos/arquitectura-software/modulos/estilos-arquitectonicos/clase"},"next":{"title":"Ejercicio","permalink":"/sasf-temarios/cursos/arquitectura-software/modulos/estilos-arquitectonicos/ejercicio"}}');var s=o(74848),i=o(28453);const r={private:!0,sidebar_class_name:"private",sidebar_label:"Cuestionario"},t=void 0,c={},l=[{value:"2. [Investigar] \xbfQu\xe9 son los &quot;Self-Contained Systems&quot; (SCS) y en qu\xe9 se diferencian de los microservicios y de la Service-Based Architecture?",id:"2-investigar-qu\xe9-son-los-self-contained-systems-scs-y-en-qu\xe9-se-diferencian-de-los-microservicios-y-de-la-service-based-architecture",level:3},{value:"3. [Investigar] \xbfC\xf3mo utiliza Netflix el patr\xf3n &quot;Backends for Frontends&quot; (BFF) junto con su estilo de microservicios y qu\xe9 problema arquitect\xf3nico resuelve?",id:"3-investigar-c\xf3mo-utiliza-netflix-el-patr\xf3n-backends-for-frontends-bff-junto-con-su-estilo-de-microservicios-y-qu\xe9-problema-arquitect\xf3nico-resuelve",level:3},{value:"4. [Investigar] \xbfQu\xe9 es el patr\xf3n &quot;Strangler Fig Application&quot; modernizado con feature flags y c\xf3mo lo implementan empresas como LaunchDarkly para migraci\xf3n de estilos arquitect\xf3nicos?",id:"4-investigar-qu\xe9-es-el-patr\xf3n-strangler-fig-application-modernizado-con-feature-flags-y-c\xf3mo-lo-implementan-empresas-como-launchdarkly-para-migraci\xf3n-de-estilos-arquitect\xf3nicos",level:3},{value:"5. [Conectar] La clase cubre Monolito como estilo con sus ventajas y desventajas. \xbfC\xf3mo se relaciona esto con el concepto de &quot;Majestic Monolith&quot; que defiende DHH (David Heinemeier Hansson) en Basecamp?",id:"5-conectar-la-clase-cubre-monolito-como-estilo-con-sus-ventajas-y-desventajas-c\xf3mo-se-relaciona-esto-con-el-concepto-de-majestic-monolith-que-defiende-dhh-david-heinemeier-hansson-en-basecamp",level:3},{value:"6. [Conectar] La clase menciona la Arquitectura en Capas y sus desventajas (sangr\xeda de capas, Big Ball of Mud). \xbfC\xf3mo aborda la &quot;Clean Layered Architecture&quot; de Simon Brown este problema usando el C4 Model como gu\xeda?",id:"6-conectar-la-clase-menciona-la-arquitectura-en-capas-y-sus-desventajas-sangr\xeda-de-capas-big-ball-of-mud-c\xf3mo-aborda-la-clean-layered-architecture-de-simon-brown-este-problema-usando-el-c4-model-como-gu\xeda",level:3},{value:"7. [Conectar] La clase cubre Event-Driven Architecture como estilo arquitect\xf3nico. \xbfC\xf3mo relaciona <em>&quot;Flow Architecture&quot;</em> de James Urquhart el estilo Pipes-and-Filters con EDA para crear arquitecturas de streaming reactivas?",id:"7-conectar-la-clase-cubre-event-driven-architecture-como-estilo-arquitect\xf3nico-c\xf3mo-relaciona-flow-architecture-de-james-urquhart-el-estilo-pipes-and-filters-con-eda-para-crear-arquitecturas-de-streaming-reactivas",level:3},{value:"8. [Cuestionar] \xbfEs la Arquitectura Hexagonal (Puertos y Adaptadores) un estilo arquitect\xf3nico en s\xed mismo o es un patr\xf3n que puede aplicarse dentro de otros estilos? \xbfQu\xe9 opinan Alistair Cockburn y Mark Richards al respecto?",id:"8-cuestionar-es-la-arquitectura-hexagonal-puertos-y-adaptadores-un-estilo-arquitect\xf3nico-en-s\xed-mismo-o-es-un-patr\xf3n-que-puede-aplicarse-dentro-de-otros-estilos-qu\xe9-opinan-alistair-cockburn-y-mark-richards-al-respecto",level:3},{value:"9. [Cuestionar] \xbfSon los microservicios simplemente una implementaci\xf3n moderna del estilo Cliente-Servidor con m\xe1s capas, o representan una categor\xeda fundamentalmente diferente?",id:"9-cuestionar-son-los-microservicios-simplemente-una-implementaci\xf3n-moderna-del-estilo-cliente-servidor-con-m\xe1s-capas-o-representan-una-categor\xeda-fundamentalmente-diferente",level:3},{value:"10. [Cuestionar] \xbfEs la Arquitectura en Capas (Layered) un antipatr\xf3n en sistemas modernos? Contrast\xe1 la cr\xedtica de Robert C. Martin con la defensa de Simon Brown.",id:"10-cuestionar-es-la-arquitectura-en-capas-layered-un-antipatr\xf3n-en-sistemas-modernos-contrast\xe1-la-cr\xedtica-de-robert-c-martin-con-la-defensa-de-simon-brown",level:3}];function d(e){const a={code:"code",em:"em",h3:"h3",hr:"hr",p:"p",strong:"strong",...(0,i.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(a.h3,{id:"2-investigar-qu\xe9-son-los-self-contained-systems-scs-y-en-qu\xe9-se-diferencian-de-los-microservicios-y-de-la-service-based-architecture",children:'2. [Investigar] \xbfQu\xe9 son los "Self-Contained Systems" (SCS) y en qu\xe9 se diferencian de los microservicios y de la Service-Based Architecture?'}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),': Self-Contained Systems (SCS) es un estilo arquitect\xf3nico formalizado por Stefan Tilkov y la comunidad de innoQ que propone sistemas aut\xf3nomos que contienen su propia UI, l\xf3gica de negocio y base de datos. A diferencia de microservicios, donde una UI web puede componerse de m\xfaltiples servicios, en SCS cada sistema tiene su propia UI completa. A diferencia de Service-Based Architecture, los SCS no comparten base de datos e incluyen la capa de presentaci\xf3n. La regla fundamental es "cada SCS es una aplicaci\xf3n web independiente" que puede desplegarse, escalarse y desarrollarse de forma aut\xf3noma, con integraci\xf3n solo a trav\xe9s de enlaces en la UI y eventos as\xedncronos en el backend.']}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),": Tilkov argumenta que SCS resuelve el principal dolor de microservicios: la composici\xf3n de UI. En microservicios con una SPA React, el frontend se convierte en un monolito que orquesta llamadas a m\xfaltiples servicios \u2014perdiendo autonom\xeda de equipo. En SCS, el equipo de Pedidos es due\xf1o de la p\xe1gina de pedidos completa (frontend + backend + DB). Esto tiene m\xe1s sentido en dominios donde las funcionalidades son naturalmente independientes (ej: un portal bancario con secciones de cuentas, inversiones, pr\xe9stamos). La clase cubri\xf3 microservicios y SBA pero no explor\xf3 c\xf3mo la UI impacta la descomposici\xf3n arquitect\xf3nica."]}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"3-investigar-c\xf3mo-utiliza-netflix-el-patr\xf3n-backends-for-frontends-bff-junto-con-su-estilo-de-microservicios-y-qu\xe9-problema-arquitect\xf3nico-resuelve",children:'3. [Investigar] \xbfC\xf3mo utiliza Netflix el patr\xf3n "Backends for Frontends" (BFF) junto con su estilo de microservicios y qu\xe9 problema arquitect\xf3nico resuelve?'}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),": El patr\xf3n Backends for Frontends (BFF), documentado por Sam Newman y utilizado extensivamente por Netflix, consiste en crear una capa de backend espec\xedfica por tipo de cliente (mobile BFF, web BFF, TV BFF, etc.). Cada BFF orquesta llamadas a m\xfaltiples microservicios y adapta la respuesta al formato \xf3ptimo para ese cliente. Resuelve el problema de que una API de microservicios gen\xe9rica obliga a cada cliente a hacer m\xfaltiples round-trips (N+1 problem en el frontend) y a procesar datos en formatos no \xf3ptimos. Con BFF, el cliente mobile recibe exactamente los datos que necesita en un solo request, reduciendo latencia y consumo de bater\xeda."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),": Netflix present\xf3 este patr\xf3n en su blog t\xe9cnico y Sam Newman lo formaliz\xf3 en ",(0,s.jsx)(a.em,{children:"Building Microservices"})," (2\xaa edici\xf3n). La clase mencion\xf3 API Gateway pero no BFF. La diferencia es sutil pero importante: un API Gateway es una capa de ruteo y cross-cutting concerns (auth, rate limiting), mientras que un BFF contiene l\xf3gica de orquestaci\xf3n espec\xedfica por cliente. Para E-Commerce Platform, un Mobile BFF podr\xeda agrupar datos de cat\xe1logo, carrito y recomendaciones en una sola respuesta optimizada para la app mobile, mientras que el Web BFF devolver\xeda datos m\xe1s detallados porque la web tiene m\xe1s ancho de banda y pantalla."]}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"4-investigar-qu\xe9-es-el-patr\xf3n-strangler-fig-application-modernizado-con-feature-flags-y-c\xf3mo-lo-implementan-empresas-como-launchdarkly-para-migraci\xf3n-de-estilos-arquitect\xf3nicos",children:'4. [Investigar] \xbfQu\xe9 es el patr\xf3n "Strangler Fig Application" modernizado con feature flags y c\xf3mo lo implementan empresas como LaunchDarkly para migraci\xf3n de estilos arquitect\xf3nicos?'}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),": El Strangler Fig Application modernizado utiliza ",(0,s.jsx)(a.strong,{children:"feature flags"})," para redirigir tr\xe1fico incrementalmente entre la vieja y la nueva implementaci\xf3n sin cambiar el routing a nivel de infraestructura. En lugar de configurar un proxy o API Gateway para redirigir ",(0,s.jsx)(a.code,{children:"/orders"})," al nuevo servicio, se usa un feature flag que el c\xf3digo del monolito eval\xfaa en runtime: si ",(0,s.jsx)(a.code,{children:"use-new-payment-service"})," est\xe1 activo para el 10% de usuarios, el monolito delega la operaci\xf3n de pago al nuevo microservicio; para el 90% restante, usa la l\xf3gica legacy. LaunchDarkly y otras plataformas permiten modificar estos porcentajes desde un dashboard sin deploy, e incluso hacer targeting por atributos de usuario (pa\xeds, plan, tenant)."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),": Aunque la clase cubri\xf3 Strangler Fig, no abord\xf3 su implementaci\xf3n moderna con feature flags, que es c\xf3mo se hace en la pr\xe1ctica hoy. Martin Fowler destac\xf3 esta evoluci\xf3n en su blog (2016), y empresas como Facebook y Google migran infraestructura cr\xedtica con este enfoque. La ventaja arquitect\xf3nica es enorme: pod\xe9s probar el nuevo servicio en producci\xf3n con 1% de tr\xe1fico, monitorear errores y performance, y solo escalar al 100% cuando ten\xe9s confianza. Si algo falla, desactiv\xe1s el flag en segundos sin tocar infraestructura."]}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"5-conectar-la-clase-cubre-monolito-como-estilo-con-sus-ventajas-y-desventajas-c\xf3mo-se-relaciona-esto-con-el-concepto-de-majestic-monolith-que-defiende-dhh-david-heinemeier-hansson-en-basecamp",children:'5. [Conectar] La clase cubre Monolito como estilo con sus ventajas y desventajas. \xbfC\xf3mo se relaciona esto con el concepto de "Majestic Monolith" que defiende DHH (David Heinemeier Hansson) en Basecamp?'}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),': DHH defiende el "Majestic Monolith" como una arquitectura donde toda la l\xf3gica de negocio reside en un solo proceso (Ruby on Rails en el caso de Basecamp) pero con patrones internos de modularizaci\xf3n fuertes: bounded contexts l\xf3gicos, servicios de dominio expl\xedcitos, y extracci\xf3n de responsabilidades transversales (jobs as\xedncronos con ActiveJob, caching agresivo). La diferencia con el monolito tradicional de la clase es que el Majestic Monolith aplica ',(0,s.jsx)(a.strong,{children:"disciplina de arquitectura sin abandonar el deploy \xfanico"}),". DHH argumenta que la complejidad distribuida de microservicios no se justifica para la mayor\xeda de aplicaciones web, y que un mon\xf3logo bien dise\xf1ado puede escalar a millones de usuarios con caching y background jobs."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),': DHH formaliz\xf3 el t\xe9rmino en su blog (2020) como respuesta a la "microservicio-man\xeda." Sam Newman, en la 2\xaa edici\xf3n de ',(0,s.jsx)(a.em,{children:"Building Microservices"}),', cita a Basecamp como ejemplo de que "no necesit\xe1s microservicios para escalar." Esto conecta con lo visto en clase sobre el Monolito Modular, pero agrega una perspectiva pol\xe9mica: tal vez el monolito no sea un estado transitorio hacia microservicios, sino el destino final correcto para la mayor\xeda de sistemas. La diferencia clave con la clase es que DHH considera el monolito como fin, no como medio.']}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"6-conectar-la-clase-menciona-la-arquitectura-en-capas-y-sus-desventajas-sangr\xeda-de-capas-big-ball-of-mud-c\xf3mo-aborda-la-clean-layered-architecture-de-simon-brown-este-problema-usando-el-c4-model-como-gu\xeda",children:'6. [Conectar] La clase menciona la Arquitectura en Capas y sus desventajas (sangr\xeda de capas, Big Ball of Mud). \xbfC\xf3mo aborda la "Clean Layered Architecture" de Simon Brown este problema usando el C4 Model como gu\xeda?'}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),": Simon Brown propone que la Arquitectura en Capas no es inherentemente mala \u2014el problema es que los equipos la implementan sin ",(0,s.jsx)(a.strong,{children:"l\xedmites expl\xedcitos entre capas"}),'. Su "Clean Layered Architecture" usa el C4 Model como herramienta de dise\xf1o: en el Nivel 3 (Component), cada componente tiene una interfaz p\xfablica expl\xedcita y la regla de dependencia es unidireccional. La novedad es que Brown insiste en que la estructura de paquetes debe reflejar las capas l\xf3gicas, y que herramientas como ArchUnit deben validar en CI/CD que no haya violaciones. No es la estructura de capas lo que falla, es la falta de disciplina para mantenerla.']}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),": En ",(0,s.jsx)(a.em,{children:"Software Architecture for Developers"}),' (2014-2023), Brown argumenta que la Arquitectura en Capas es perfectamente v\xe1lida como "estilo por defecto" si se aplica con: (1) inversi\xf3n de dependencias entre capas (interfaces en capa de dominio), (2) verificaci\xf3n automatizada de dependencias, y (3) separaci\xf3n en componentes, no solo paquetes. Esto conecta lo visto en clase (Capas como estilo con desventajas) con una perspectiva m\xe1s matizada: Capas + disciplina = arquitectura mantenible; Capas sin disciplina = Big Ball of Mud. La diferencia es la ingenier\xeda, no el estilo.']}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsxs)(a.h3,{id:"7-conectar-la-clase-cubre-event-driven-architecture-como-estilo-arquitect\xf3nico-c\xf3mo-relaciona-flow-architecture-de-james-urquhart-el-estilo-pipes-and-filters-con-eda-para-crear-arquitecturas-de-streaming-reactivas",children:["7. [Conectar] La clase cubre Event-Driven Architecture como estilo arquitect\xf3nico. \xbfC\xf3mo relaciona ",(0,s.jsx)(a.em,{children:'"Flow Architecture"'})," de James Urquhart el estilo Pipes-and-Filters con EDA para crear arquitecturas de streaming reactivas?"]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),": James Urquhart, en ",(0,s.jsx)(a.em,{children:"Flow Architectures"}),' (2021), propone que el futuro de la integraci\xf3n de sistemas es el modelo de "flow": eventos (EDA) como transporte y pipes-and-filters como procesamiento. Un evento llega a un topic de Kafka, un stream processor (Kafka Streams, Apache Flink) aplica una cadena de filtros y transformaciones, y emite nuevos eventos o actualiza materialized views. Esto combina la desacoplaci\xf3n temporal de EDA con la composicionalidad de Pipes-and-Filters. El resultado es una arquitectura donde el flujo de datos es el ciudadano de primera clase, no los servicios. Wardley llama a esto "the future of integration" porque elimina el acoplamiento punto a punto entre servicios y lo reemplaza con procesamiento sobre streams.']}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),": La clase trat\xf3 EDA y Pipes-and-Filters como estilos separados, pero Urquhart argumenta que la convergencia de ambos es la tendencia dominante en arquitecturas modernas (event streaming + stream processing). Empresas como Netflix (Keystone), Uber (real-time pipelines) y LinkedIn (Apache Samza) implementan esta convergencia. Para E-Commerce Platform, esto significa que en lugar de que el servicio de Pagos llame a Inventario y Notificaciones, todos los servicios publican eventos a streams y consumen de streams procesados."]}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"8-cuestionar-es-la-arquitectura-hexagonal-puertos-y-adaptadores-un-estilo-arquitect\xf3nico-en-s\xed-mismo-o-es-un-patr\xf3n-que-puede-aplicarse-dentro-de-otros-estilos-qu\xe9-opinan-alistair-cockburn-y-mark-richards-al-respecto",children:"8. [Cuestionar] \xbfEs la Arquitectura Hexagonal (Puertos y Adaptadores) un estilo arquitect\xf3nico en s\xed mismo o es un patr\xf3n que puede aplicarse dentro de otros estilos? \xbfQu\xe9 opinan Alistair Cockburn y Mark Richards al respecto?"}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),': Hay desacuerdo. Alistair Cockburn, el creador, lo llama "patr\xf3n arquitect\xf3nico" (no un estilo), argumentando que Hexagonal es una forma de estructurar ',(0,s.jsx)(a.strong,{children:"dentro"})," de un estilo m\xe1s amplio: pod\xe9s tener un microservicio con arquitectura hexagonal, un monolito con arquitectura hexagonal, o incluso un servicio en una Event-Driven Architecture con puertos y adaptadores. Mark Richards, en ",(0,s.jsx)(a.em,{children:"Software Architecture Patterns"}),", lo clasifica como un patr\xf3n de dise\xf1o arquitect\xf3nico, distingui\xe9ndolo de estilos (como microservicios o event-driven), que definen la topolog\xeda del sistema completo. Hexagonal no prescribe c\xf3mo se comunican los servicios entre s\xed (eso lo define el estilo), sino c\xf3mo se estructura ",(0,s.jsx)(a.strong,{children:"un"})," servicio."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),": La clase present\xf3 Hexagonal como un patr\xf3n separado (M\xf3dulo 04), no como un estilo (M\xf3dulo 02). Esto refleja la opini\xf3n de Cockburn, pero hay arquitectos que lo tratan como estilo porque impone una topolog\xeda espec\xedfica (n\xfacleo + puertos + adaptadores). La distinci\xf3n pr\xe1ctica: si est\xe1s definiendo la arquitectura del sistema (estilo), eleg\xeds entre Monolito, Microservicios, SBA; si est\xe1s definiendo la estructura interna de cada componente, us\xe1s Hexagonal, Clean o Capas. Confundir niveles lleva a decisiones arquitect\xf3nicas mal calibradas."]}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"9-cuestionar-son-los-microservicios-simplemente-una-implementaci\xf3n-moderna-del-estilo-cliente-servidor-con-m\xe1s-capas-o-representan-una-categor\xeda-fundamentalmente-diferente",children:"9. [Cuestionar] \xbfSon los microservicios simplemente una implementaci\xf3n moderna del estilo Cliente-Servidor con m\xe1s capas, o representan una categor\xeda fundamentalmente diferente?"}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),": Cr\xedticos como Stefan Tilkov argumentan que los microservicios no son un nuevo estilo \u2014son Cliente-Servidor distribuido con Domain-Driven Design. Cada microservicio es un servidor que expone una API (REST/gRPC) y otros servicios act\xfaan como clientes. Lo que cambi\xf3 es la granularidad y la disciplina de dominio, no el estilo topol\xf3gico. Defensores como Sam Newman y Chris Richardson argumentan que microservicios s\xed es un estilo diferente porque introduce constraints que Cliente-Servidor no tiene: database per service, smart endpoints and dumb pipes, independencia de deploy como requisito no negociable."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),': Esta es una discusi\xf3n taxon\xf3mica con implicaciones pr\xe1cticas. Si microservicios es "solo" Cliente-Servidor, entonces todos los problemas de Cliente-Servidor aplican (acoplamiento temporal, punto \xfanico de fallo si no hay redundancia). Si es un estilo nuevo, entonces requiere sus propias herramientas de dise\xf1o, patrones y heur\xedsticas. Mark Richards, en ',(0,s.jsx)(a.em,{children:"Fundamentals of Software Architecture"})," con Neal Ford, trata microservicios como un estilo separado con su propio conjunto de trade-offs y patrones, posici\xf3n que adopt\xf3 la clase en M\xf3dulo 02."]}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"10-cuestionar-es-la-arquitectura-en-capas-layered-un-antipatr\xf3n-en-sistemas-modernos-contrast\xe1-la-cr\xedtica-de-robert-c-martin-con-la-defensa-de-simon-brown",children:"10. [Cuestionar] \xbfEs la Arquitectura en Capas (Layered) un antipatr\xf3n en sistemas modernos? Contrast\xe1 la cr\xedtica de Robert C. Martin con la defensa de Simon Brown."}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),": Robert C. Martin en ",(0,s.jsx)(a.em,{children:"Clean Architecture"})," critica la Arquitectura en Capas porque las dependencias van hacia abajo (capa de negocio depende de capa de persistencia), lo que acopla el dominio a la infraestructura. Su soluci\xf3n es invertir las dependencias (el dominio define interfaces, la infraestructura las implementa). Simon Brown defiende que Capas no es inherentemente mala: el problema es que los equipos la implementan sin disciplina. Si cada capa expone una interfaz y las dependencias est\xe1n controladas (con ArchUnit, por ejemplo), Capas es una arquitectura perfectamente mantenible y m\xe1s simple que Clean/Hexagonal para equipos peque\xf1os."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),': Este debate refleja una tensi\xf3n real: pragmatismo vs pureza. La clase present\xf3 Capas con sus pros y contras, pero no profundiz\xf3 en la controversia. El "sangrado de capas" que describe Uncle Bob es un problema real en proyectos longevos, pero la complejidad adicional de Clean Architecture tambi\xe9n tiene costo. La respuesta sensata de Brown es: us\xe1 Capas pero con dependencias controladas; si el proyecto crece, refactoriz\xe1 hacia dentro con inversi\xf3n de dependencias progresiva.']}),"\n",(0,s.jsx)(a.hr,{})]})}function u(e={}){const{wrapper:a}={...(0,i.R)(),...e.components};return a?(0,s.jsx)(a,{...e,children:(0,s.jsx)(d,{...e})}):d(e)}},28453(e,a,o){o.d(a,{R:()=>r,x:()=>t});var n=o(96540);const s={},i=n.createContext(s);function r(e){const a=n.useContext(i);return n.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function t(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:r(e.components),n.createElement(i.Provider,{value:a},e.children)}}}]);